    if t <= k:
        # Phase 1: Wave is growing
        result = t
    elif t <= n:
        # Phase 2: Wave is moving at full length k
        result = k
    else:
        # Phase 3: Wave is shrinking as it reaches the end
        # Result is k - (t - n)
        result = n + k - t

    # Output the result
    print(result)

