import sys

# Set recursion limit for safety, though 20 is more than enough for a 19-digit number
sys.setrecursionlimit(2000)

def solve():
    # Read input from standard input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    a_str = input_data[0]
    b_str = input_data[1]

    # If length of a is shorter than b, the largest permutation of a is the maximal possible result
    if len(a_str) < len(b_str):
        print("".join(sorted(list(a_str), reverse=True)))
        return

    # If lengths are equal, use backtracking to find the largest permutation <= b
    # Number of digits is up to 18, so an efficient O(digits^2) search is fast enough
    counts = [0] * 10
    for char in a_str:
        counts[int(char)] += 1

    res = [""] * len(a_str)

    def get_smallest(c):
        """Helper to form the smallest possible sequence from remaining digit counts."""
        parts = []
        for d in range(10):
            if c[d] > 0:
                parts.append(str(d) * c[d])
        return "".join(parts)

    def fill_descending(start_idx, c):
        """Helper to fill the remaining slots with available digits in descending order."""
        curr = start_idx
        for d in range(9, -1, -1):
            num_d = c[d]
            for _ in range(num_d):
                res[curr] = str(d)
                curr += 1

    def backtrack(idx):
        # Base case: reached the end of the number
        if idx == len(b_str):
            return True

        target = int(b_str[idx])

        # First priority: Try to match the digit of b at current index exactly
        if counts[target] > 0:
            counts[target] -= 1
            # A number starting with target can only be <= b if the smallest suffix we can form
            # starting with remaining digits is <= the corresponding suffix of b.
            if get_smallest(counts) <= b_str[idx+1:]:
                res[idx] = str(target)
                if backtrack(idx + 1):
                    return True
            # Backtrack if matching target didn't lead to a solution
            counts[target] += 1

        # Second priority: Try picking the largest digit smaller than target
        for d in range(target - 1, -1, -1):
            # According to the rules, the number cannot start with a zero
            if idx == 0 and d == 0:
                continue
            if counts[d] > 0:
                res[idx] = str(d)
                counts[d] -= 1
                # Once a smaller digit is placed, the suffix is maximized by filling it descendingly
                fill_descending(idx + 1, counts)
                return True

        return False

    if backtrack(0):
        print("".join(res))

if __name__ == '__main__':
    solve()

