    w1 = [] # examples currently in a spot designated for a regular test
    w0 = [] # regular tests currently in a spot designated for an example
    o1 = [] # examples currently outside target names
    o0 = [] # regular tests currently outside target names

    for name, type_ in files:
        if type_ == 1:
            if name in type1_targets:
                continue
            elif name in type0_targets:
                w1.append(name)
            else:
                o1.append(name)
        else:
            if name in type0_targets:
                continue
            elif name in type1_targets:
                w0.append(name)
            else:
                o0.append(name)

    # Identify target names that are not used by any file currently
    e1 = [name for name in type1_targets if name not in all_current_names]
    e0 = [name for name in type0_targets if name not in all_current_names]

    moves = []

    # Generator for temporary file names that won't conflict with targets (digits)
    def gen_tmp_names():
