import sys
import string

def solve():
    # Reading all input at once for efficiency
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    files = []
    for i in range(n):
        name = input_data[2*i + 1]
        type_ = int(input_data[2*i + 2])
        files.append((name, type_))

    # Total number of examples (type 1 tests)
    e = sum(f[1] for f in files)

    # Target string sets for examples and regular tests
    type1_targets = {str(i) for i in range(1, e + 1)}
    type0_targets = {str(i) for i in range(e + 1, n + 1)}

    all_current_names = {f[0] for f in files}

    w1 = [] # examples currently in a spot designated for a regular test
    w0 = [] # regular tests currently in a spot designated for an example
    o1 = [] # examples currently outside target names
    o0 = [] # regular tests currently outside target names

    for name, type_ in files:
        if type_ == 1:
            if name in type1_targets:
                continue
            elif name in type0_targets:
                w1.append(name)
            else:
                o1.append(name)
        else:
            if name in type0_targets:
                continue
            elif name in type1_targets:
                w0.append(name)
            else:
                o0.append(name)

    # Identify target names that are not used by any file currently
    e1 = [name for name in type1_targets if name not in all_current_names]
    e0 = [name for name in type0_targets if name not in all_current_names]

    moves = []

    # Generator for temporary file names that won't conflict with targets (digits)
    def gen_tmp_names():
        for c1 in string.ascii_lowercase:
            for c2 in string.ascii_lowercase:
                for c3 in string.ascii_lowercase:
                    for c4 in string.ascii_lowercase:
                        yield c1+c2+c3+c4

    tmp_gen = gen_tmp_names()

    while w1 or w0 or o1 or o0:
        if e1 and (w1 or o1):
            if w1:
                f = w1.pop()
                s = e1.pop()
                moves.append(f"move {f} {s}")
                e0.append(f) # Old spot f was in T0, now it's free
            else:
                f = o1.pop()
                s = e1.pop()
                moves.append(f"move {f} {s}")
        elif e0 and (w0 or o0):
            if w0:
                f = w0.pop()
                s = e0.pop()
                moves.append(f"move {f} {s}")
                e1.append(f) # Old spot f was in T1, now it's free
            else:
                f = o0.pop()
                s = e0.pop()
                moves.append(f"move {f} {s}")
        else:
            # Cycle scenario: no free target spots available
            f = w1.pop()
            while True:
                tmp_name = next(tmp_gen)
                if tmp_name not in all_current_names:
                    break
            moves.append(f"move {f} {tmp_name}")
            all_current_names.add(tmp_name)
            o1.append(tmp_name) # File is now at a non-target spot
            e0.append(f) # Spot f (in T0) is now free

    print(len(moves))
    if moves:
        sys.stdout.write("\n".join(moves) + "\n")

if __name__ == "__main__":
    solve()

