def solve():
    # Read input from standard input
    # The first line contains n, k, t
    try:
        line = sys.stdin.readline()
        if not line:
            return
        n, k, t = map(int, line.split())
    except ValueError:
        return

    # Determine the number of spectators standing based on the current time t
    if t <= k:
        # Phase 1: Wave is growing
