def check_win(grid):
    """
    Checks if the grid contains any sequence of 5 or more 'X's
    horizontally, vertically, or diagonally.
    """
    N = 10
    for r in range(N):
        for c in range(N):
            # Check horizontal: 5 in a row to the right
            if c + 4 < N:
                if all(grid[r][c + i] == 'X' for i in range(5)):
                    return True

            # Check vertical: 5 in a row downwards
            if r + 4 < N:
                if all(grid[r + i][c] == 'X' for i in range(5)):
                    return True

            # Check diagonal: 5 in a row down-right
            if r + 4 < N and c + 4 < N:
                if all(grid[r + i][c + i] == 'X' for i in range(5)):
                    return True

            # Check diagonal: 5 in a row down-left
            if r + 4 < N and c - 4 >= 0:
                if all(grid[r + i][c - i] == 'X' for i in range(5)):
                    return True
    return False

def solve():
    # Read all input and remove any extra whitespace to ensure a clean character list
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    # Concatenate all fragments and build a list of 10x10 characters
    full_text = "".join(input_data)
    if len(full_text) < 100:
        return

    # Create the matrix representation
    grid = [list(full_text[i:i + 10]) for i in range(0, 100, 10)]

    # Try placing Alice's 'X' in every empty '.' cell
    for r in range(10):
        for c in range(10):
            if grid[r][c] == '.':
                # Place an 'X' temporarily
                grid[r][c] = 'X'

                # Check if this move wins the game for Alice
                if check_win(grid):
                    print("YES")
                    return

                # Undo the move to try the next empty cell
                grid[r][c] = '.'

    # If no move results in Alice winning, output NO
    print("NO")

