import sys

def solve():
    # Read n and k from standard input
    input_data = sys.stdin.read().split()
    if len(input_data) < 2:
        return

    try:
        n = int(input_data[0])
        k = int(input_data[1])
    except ValueError:
        return

    # A matrix of size n x n can have at most n^2 ones.
    if k > n * n:
        print("-1")
        return

    # Initialize an n x n matrix with zeros
    matrix = [[0 for _ in range(n)] for _ in range(n)]

    current_k = k
    # Iterate through the matrix in row-major order (i, j)
    for i in range(n):
        for j in range(n):
            # If all k ones are already placed, we can stop early
            if current_k <= 0:
                break

            # If this cell is already filled, skip it
            if matrix[i][j] == 1:
                continue

            if i == j:
                # Diagonal elements only require one bit to stay symmetric
                if current_k >= 1:
                    matrix[i][j] = 1
                    current_k -= 1
            elif i < j:
                # Off-diagonal elements (i, j) require (j, i) to be 1 
                # to maintain symmetry. This requires two bits.
                # We check i < j to ensure we don't try to fill the pair twice.
                if current_k >= 2:
                    matrix[i][j] = 1
                    matrix[j][i] = 1
                    current_k -= 2

        if current_k <= 0:
            break

    # Check if all k ones were placed symmetrically
    if current_k == 0:
        for row in matrix:
            # Print each row of the matrix separated by spaces
            print(*(row))
    else:
        # Not possible to place exactly k ones symmetrically
        print("-1")

if __name__ == "__main__":
    solve()

